// Public known-answer transfer fixtures. No discrete logarithm solver is run.
#include "quotient_arithmetic.hpp"
void emit_point(const EC&p){if(p.zero){std::cout<<"{\"infinity\":true}";return;}std::cout<<"{\"infinity\":false,\"x\":\""<<scalar(p.x).x<<"\",\"y\":\""<<scalar(p.y).x<<"\"}";}
int main(int argc,char**argv){try{require(argc==2,"usage: roundtrip_receipt study-directory");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));auto actual=read_json(root+"/evidence/final-kernel-check/actual-cover-torsion.json");std::vector<G> basis;for(auto&v:actual.at("basis").arr)basis.push_back(G{polynomial(v.at("U")),polynomial(v.at("V"))});require(basis.size()==6,"receipt basis length");
    auto modules=read_json(root+"/../nist_cover_separator_20261115/data/modules-192.json");M a{},form{};bool found=false;for(auto&row:modules.at("modules").arr)if(row.at("candidate").integer()==139&&row.at("d").integer()==7){block(a,row.at("E_Frobenius"),2,0);block(a,row.at("Prym_Frobenius"),4,2);block(form,row.at("E_Weil"),2,0);block(form,row.at("Prym_Weil"),4,2);found=true;}require(found,"receipt module");
    EC base(F(Poly<Z>{Z(mpz_class("188DA80EB03090F67CBF20EB43A18800F4FF0AFD82FF1012",16))}),F(Poly<Z>{Z(mpz_class("07192B95FFC8DA78631011ED6B24CDD573F977A11E794811",16))}));mpz_class r("6277101735386680763835789423176059013767194773182842284081"),inverse6,six=6;require(mpz_invert(inverse6.get_mpz_t(),six.get_mpz_t(),r.get_mpz_t())!=0,"receipt inverse6");std::vector<mpz_class> scalars{mpz_class(0),mpz_class(1),mpz_class(37),mpz_class(r-1),public_scalar(r)};
    std::ifstream in(root+"/evidence/final-kernel-check/kernels.jsonl");require(bool(in),"receipt kernels");std::string line;int kernels=0;while(std::getline(in,line)){Parser p{line};auto row=p.value();Basis coordinates;for(auto&v:row.at("rref_basis").arr){require(v.arr.size()==6,"receipt kernel shape");V vv{};for(int i=0;i<6;++i)vv[i]=v.arr[i].integer();coordinates.push_back(vv);}Quotient q(basis,coordinates,a,form);
        for(size_t i=0;i<scalars.size();++i){EC source=times(base,scalars[i]),projected=q.Tmap(q.Fmap(source)),recovered=times(projected,inverse6);std::cout<<"{\"kernel\":"<<row.at("kernel").integer()<<",\"case\":"<<i<<",\"known_scalar\":\""<<scalars[i]<<"\",\"source\":";emit_point(source);std::cout<<",\"T_F_source\":";emit_point(projected);std::cout<<",\"recovered_source\":";emit_point(recovered);std::cout<<"}\n";}
        ++kernels;
    }require(kernels==8,"receipt eight kernels");
}catch(const std::exception&e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
